<template>
  <section class="saved-simulation-report" aria-label="Saved simulation report"><header><div><p>Saved report · {{ date(report.completed_at||report.created_at) }}</p><h1>{{ report.outline?.title || 'Simulation report' }}</h1></div><a :href="`${api}/api/report/${encodeURIComponent(report.report_id)}/download`" class="research-secondary">Download report</a></header>
    <div class="saved-report-layout"><nav aria-label="Report chapters"><button v-for="(item,i) in chapters" :key="item.section_index" :class="{selected:active===i}" :aria-current="active===i?'page':undefined" @click="active=i"><span>{{ String(i+1).padStart(2,'0') }}</span>{{ title(item,i) }}</button><RouterLink :to="`/interaction/${encodeURIComponent(report.report_id)}`">Interview and discuss →</RouterLink></nav><article><p v-if="loading" role="status">Loading saved chapters…</p><p v-else-if="error" class="research-load-error" role="alert">{{ error }}</p><div v-else class="saved-report-prose" v-html="safeMarkdown(chapters[active]?.content || report.markdown_content || '')"/><footer><RouterLink :to="`/interaction/${encodeURIComponent(report.report_id)}`" class="research-primary">Discuss this report →</RouterLink></footer></article></div>
  </section>
</template>
<script setup>
import {onBeforeUnmount,ref,watch} from 'vue'
import {safeMarkdown} from '../utils/safeMarkdown.mjs'
import {researchApi as api} from '../api/research'
const props=defineProps({report:{type:Object,required:true}})
const chapters=ref([]),active=ref(0),loading=ref(false),error=ref('')
let controller,token=0
const date=value=>value?new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Unknown date'
const title=(item,i)=>props.report.outline?.sections?.[i]?.title||item.content?.match(/^#{1,6}\s+(.+)$/m)?.[1]||`Chapter ${i+1}`
watch(()=>props.report.report_id,async id=>{controller?.abort();controller=new AbortController();const generation=++token;loading.value=true;error.value='';active.value=0;try{const r=await fetch(`${api}/api/report/${encodeURIComponent(id)}/sections`,{signal:controller.signal}),b=await r.json();if(generation!==token)return;if(!r.ok||b.success===false)throw new Error(b.error||'Could not load report chapters');chapters.value=b.data?.sections||[]}catch(e){if(generation===token&&e.name!=='AbortError')error.value=e.message}finally{if(generation===token)loading.value=false}},{immediate:true})
onBeforeUnmount(()=>{token++;controller?.abort()})
</script>
