.saved-simulation-report{height:100%;overflow:auto;padding:15px 20px 30px;min-width:0}.saved-simulation-report>header{display:flex;justify-content:space-between;gap:25px;align-items:start;margin-bottom:29px}.saved-simulation-report>header p{font-size:11px;color:#697589;margin:0 0 10px}.saved-simulation-report h1{font-size:29px;font-weight:550;line-height:1.3;letter-spacing:-.8px;max-width:900px;margin:0}.saved-simulation-report>header>a{white-space:nowrap;font-size:11px}.saved-report-layout{display:grid;grid-template-columns:195px minmax(0,1fr);gap:30px}.saved-report-layout nav{display:flex;flex-direction:column;gap:5px;align-self:start;position:sticky;top:0}.saved-report-layout nav button{display:flex;gap:10px;text-align:left;padding:11px 10px;font-size:12px;line-height:1.6;border:0;border-radius:7px;background:transparent;color:#697589;cursor:pointer}.saved-report-layout nav button.selected{background:#fff3ec;color:#ad481b}.saved-report-layout nav span{font-size:10px;opacity:.75}.saved-report-layout nav>a{font-size:12px;margin:15px 10px}.saved-report-layout>article{min-width:0;max-width:950px}.saved-report-layout article>p{font-size:13px;color:#697589}.saved-report-layout footer{border-top:1px solid #edf0f4;margin-top:25px;padding-top:20px}.saved-report-prose{font-size:14px;color:#44566b;line-height:1.85;overflow-wrap:anywhere}.saved-report-prose :deep(h2){font-size:25px;color:#25364b;font-weight:550;line-height:1.35;letter-spacing:-.5px;margin:0 0 20px}.saved-report-prose :deep(h3){font-size:19px;color:#32475c;font-weight:500;margin:26px 0 13px}.saved-report-prose :deep(h4){font-size:15px;font-weight:500;margin:22px 0 11px}.saved-report-prose :deep(p){margin:0 0 16px}.saved-report-prose :deep(ul),.saved-report-prose :deep(ol){padding-left:21px;margin:14px 0 23px}.saved-report-prose :deep(li){margin:9px 0}.saved-report-prose :deep(blockquote){margin:20px 0;border-left:2px solid #d4dfeb;padding:7px 0 7px 16px;color:#647589;font-size:13px}.saved-report-prose :deep(pre){white-space:pre-wrap;background:#f8fafc;padding:15px;border-radius:7px;font-size:12px}.saved-report-prose :deep(code){font-size:12px;background:#f4f6f8;padding:2px 4px;border-radius:3px}.saved-report-prose :deep(a){color:#a34c22;text-decoration:underline}@media(max-width:900px){.saved-report-layout{grid-template-columns:minmax(0,1fr);gap:20px}.saved-report-layout nav{position:static;flex-direction:row;overflow:auto}.saved-report-layout nav button{min-width:170px}.saved-report-layout nav>a{display:none}.saved-simulation-report>header{flex-direction:column;gap:15px}.saved-simulation-report h1{font-size:26px}}@media(max-width:600px){.saved-simulation-report{padding:12px 0 25px}.saved-report-prose{font-size:13px}.saved-report-prose :deep(h2){font-size:23px}}
</style>
